/* Extracted established native layout policy; generated by extract_layout_engine.py. */
/* 4-deck without the sidebar: mixer_converge shrinks the mixer area to the FX channel
 * row, which clips the native Beat FX overlay out of sight (issue #3). Lift it to the top
 * of the view at its stock screen position. Stock still shows and hides it; only its
 * parent and position change. */
static struct {char *root,*owner,*parent;int index,box[4];} g_fx_overlay;
static void fx_overlay_restore(void) {
    __typeof__(g_fx_overlay) old=g_fx_overlay;
    memset(&g_fx_overlay,0,sizeof g_fx_overlay);
    if(!old.root||!is_class(old.root,BEATFX_CLASS))return;
    /* Do not steal the component if another stock screen already adopted it. */
    if(*(char **)(old.root+COMP_PARENT)!=old.owner||!is_class(old.parent,"N3gui5mixer15MixerAreaWidgetE"))return;
    layout_components.reparent(old.parent,old.root,old.index);
    comp_bounds(old.root,old.box[0],old.box[1],old.box[2],old.box[3]);
}
static int fx_overlay_converge(char *owner,char *mixer) {
    if(g_fx_overlay.root&&(g_fx_overlay.owner!=owner||g_fx_overlay.parent!=mixer))fx_overlay_restore();
    if(!g_fx_overlay.root) {
        char *root=child_of_class(mixer,BEATFX_CLASS,0);
        if(!root||*(char **)(root+COMP_PARENT)!=mixer)return 0;
        char **kids=*(char ***)(mixer+0x40);
        int n=*(int *)(mixer+0x50),index=-1;
        if(!ptr_ok(kids)||n<0||n>64)return 0;
        for(int i=0;i<n;i++)if(kids[i]==root)index=i;
        if(index<0)return 0;
        g_fx_overlay.root=root;g_fx_overlay.owner=owner;g_fx_overlay.parent=mixer;g_fx_overlay.index=index;
        memcpy(g_fx_overlay.box,root+COMP_BOUNDS,sizeof g_fx_overlay.box);
        layout_components.reparent(owner,root,-1);
    }
    if(*(char **)(g_fx_overlay.root+COMP_PARENT)!=owner) {memset(&g_fx_overlay,0,sizeof g_fx_overlay);return 0;}
    /* stock position in the stock mixer box, plus any parents between mixer and view */
    int x=g_mixer_box[0]+g_fx_overlay.box[0],y=g_mixer_box[1]+g_fx_overlay.box[1];
    char *p=*(char **)(mixer+COMP_PARENT);
    for(int i=0;p&&p!=owner&&i<4;i++,p=*(char **)(p+COMP_PARENT)) {
        const int *b=(const int *)(p+COMP_BOUNDS);x+=b[0];y+=b[1];
    }
    comp_bounds(g_fx_overlay.root,x,y,g_fx_overlay.box[2],g_fx_overlay.box[3]);
    return 1;
}
